CREATE TEMPORARY TABLE equipment (item_id INT PRIMARY KEY, item_name VARCHAR(40) NOT NULL, quantity INT NOT NULL CHECK (quantity >= 0)) ENGINE=InnoDB;
INSERT INTO equipment (item_id,item_name,quantity) SELECT item_id,item_name,quantity FROM equipment_input;
SELECT item_id,item_name,quantity FROM equipment ORDER BY item_id;

ALTER TABLE equipment ADD COLUMN inspected_on DATE NULL;
UPDATE equipment SET inspected_on = '2026-09-01' WHERE quantity > 0;
SELECT item_id,item_name,quantity,inspected_on FROM equipment ORDER BY item_id;
